package replay
import("context";"errors";"os";"path/filepath";"sync";"sync/atomic";"testing";"time")
func TestFileStoreReplaySurvivesRestart(t *testing.T){path:=filepath.Join(t.TempDir(),"replay.json");key:=Key{OrganizationID:"org",RequestID:"req",Nonce:"nonce"};exp:=time.Now().Add(time.Hour);if err:=NewFileStore(path).Consume(context.Background(),key,exp);err!=nil{t.Fatal(err)};if err:=NewFileStore(path).Consume(context.Background(),key,exp);!errors.Is(err,ErrReplay){t.Fatalf("restart restored authority: %v",err)}}
func TestFileStoreConcurrentReplayAtMostOnce(t *testing.T){store:=NewFileStore(filepath.Join(t.TempDir(),"replay.json"));key:=Key{OrganizationID:"org",RequestID:"req",Nonce:"nonce"};exp:=time.Now().Add(time.Hour);var ok atomic.Int64;var wg sync.WaitGroup;for i:=0;i<100;i++{wg.Add(1);go func(){defer wg.Done();if store.Consume(context.Background(),key,exp)==nil{ok.Add(1)}}()};wg.Wait();if ok.Load()!=1{t.Fatalf("success=%d want=1",ok.Load())}}
func TestCorruptReplayStoreFailsClosed(t *testing.T){path:=filepath.Join(t.TempDir(),"replay.json");if err:=os.WriteFile(path,[]byte("{corrupt"),0600);err!=nil{t.Fatal(err)};err:=NewFileStore(path).Consume(context.Background(),Key{OrganizationID:"o",RequestID:"r",Nonce:"n"},time.Now().Add(time.Hour));if !errors.Is(err,ErrStoreUnavailable){t.Fatalf("got %v",err)}}
